# Generated by GLM 5.3 NVFP4

#!/usr/bin/env bash

# Registers the Azure resource providers (namespaces) used by the Terraform
# configuration in infra/.
#
# Why: azurerm 5.0 defaults to `resource_provider_registrations = "none"`,
# meaning the Terraform provider no longer registers resource providers
# automatically (v4 did). On a fresh subscription the first apply fails with
#   MissingSubscriptionRegistration ... 409 (409 Conflict)
# The provider blocks in infra/ now list their namespaces explicitly, but this
# script is the deterministic one-time setup for a new subscription: it uses
# `--wait`, so registration has fully completed before Terraform runs.
#
# Permissions: registering a provider requires the `/register/action` action
# at subscription scope. Owner and Contributor have it; on Azure for Students
# your account is Owner of the subscription. Run once per subscription.

set -euo pipefail

if ! command -v az >/dev/null 2>&1; then
  echo "The Azure CLI (az) is required: https://aka.ms/azure-cli" >&2
  exit 1
fi

PROVIDERS=(
  "Microsoft.Resources"         # resource groups (bootstrap)
  "Microsoft.Storage"           # storage account for Terraform state (bootstrap)
  "Microsoft.App"               # Container Apps environment, apps, jobs, custom domains, certs
  "Microsoft.ContainerRegistry" # Azure Container Registry
  "Microsoft.ManagedIdentity"   # user-assigned managed identity for ACR pulls
  "Microsoft.Authorization"      # role assignments (AcrPull)
  "Microsoft.Network"           # VNet + subnet for the container app environment
  "Microsoft.OperationalInsights" # Log Analytics workspace for app/job logs
  # Add when introduced:
  # "Microsoft.DBforPostgreSQL"     # Azure Database for PostgreSQL (if replacing Neon)
  # "Microsoft.KeyVault"            # Key Vault (secrets / certificates)
)

echo "Subscription: $(az account show --query name -o tsv)"
echo

for provider in "${PROVIDERS[@]}"; do
  echo "Registering ${provider}..."
  az provider register --namespace "${provider}" --wait
done

echo
echo "Registration states:"
for provider in "${PROVIDERS[@]}"; do
  state="$(az provider show --namespace "${provider}" --query registrationState -o tsv)"
  printf '  %-30s %s\n' "${provider}" "${state}"
done
